#!/usr/bin/env python3
"""Staged IPv6 prefix-lookup pipeline: compiler and lookup.

Reads one JSON request per line from stdin and writes exactly one JSON
response per line to stdout.  Requests are independent; malformed input on
one line yields {"status":"invalid"} and processing continues.

The compile operation chooses cut depths 0 = c[0] < ... < c[S] = 128 with
c[i+1]-c[i] <= max_stride that minimize, exactly, the peak stage utilization
max_i U[i]/capacities[i] of the fully determined node layout, and serializes
that layout as a self-contained lookup image.  The lookup operation fully
validates an image (structure, ordering, cost accounting, reachability,
canonical spelling) and then answers longest-prefix-match queries.
"""

import array
import bisect
import ctypes
import json
import math
import os
import re
import subprocess
import sys
import tempfile
import traceback

HERE = os.path.dirname(os.path.abspath(__file__))


class Invalid(Exception):
    """Any violation of the request/image contract."""


# ---------------------------------------------------------------------------
# IPv6 addresses and prefixes
# ---------------------------------------------------------------------------

_HEX = frozenset('0123456789abcdefABCDEF')
_DIG = frozenset('0123456789')


def parse_addr(s):
    """Parse a pure hexadecimal IPv6 address (compressed or expanded,
    case-insensitive) into its unsigned 128-bit value.  Raises Invalid."""
    if type(s) is not str:
        raise Invalid()
    if '::' in s:
        if s.count('::') != 1:
            raise Invalid()
        left, right = s.split('::')
        lg = left.split(':') if left else []
        rg = right.split(':') if right else []
        if any(g == '' for g in lg) or any(g == '' for g in rg):
            raise Invalid()
        if len(lg) + len(rg) > 7:
            raise Invalid()
        groups = lg + ['0'] * (8 - len(lg) - len(rg)) + rg
    else:
        groups = s.split(':')
        if len(groups) != 8 or any(g == '' for g in groups):
            raise Invalid()
    val = 0
    for g in groups:
        if len(g) > 4:
            raise Invalid()
        for ch in g:
            if ch not in _HEX:
                raise Invalid()
        val = (val << 16) | int(g, 16)
    return val


def parse_prefix(s):
    """Parse '<addr>/<len>' with a canonical-form-free address part and a
    strict decimal length.  Returns (network_value, length)."""
    if type(s) is not str:
        raise Invalid()
    if s.count('/') != 1:
        raise Invalid()
    a, ln = s.split('/')
    if not ln or len(ln) > 3:
        raise Invalid()
    for ch in ln:
        if ch not in _DIG:
            raise Invalid()
    if len(ln) > 1 and ln[0] == '0':
        raise Invalid()
    length = int(ln)
    if length > 128:
        raise Invalid()
    val = parse_addr(a)
    if val & ((1 << (128 - length)) - 1):
        raise Invalid()
    return val, length


def fmt_addr(v):
    """Canonical pure hexadecimal form of a 128-bit address."""
    groups = [(v >> (112 - 16 * i)) & 0xFFFF for i in range(8)]
    best_start = -1
    best_len = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i
            while j < 8 and groups[j] == 0:
                j += 1
            if j - i >= 2 and j - i > best_len:
                best_len = j - i
                best_start = i
            i = j
        else:
            i += 1
    if best_start >= 0:
        left = [format(g, 'x') for g in groups[:best_start]]
        right = [format(g, 'x') for g in groups[best_start + best_len:]]
        return ':'.join(left) + '::' + ':'.join(right)
    return ':'.join([format(g, 'x') for g in groups])


def fmt_prefix(v, length):
    return fmt_addr(v) + '/' + str(length)


# ---------------------------------------------------------------------------
# Codec arithmetic
# ---------------------------------------------------------------------------

def align8(x):
    return (x + 7) & ~7


def align64(x):
    return (x + 63) & ~63


# ---------------------------------------------------------------------------
# Fully determined node layout
# ---------------------------------------------------------------------------

def build_layout(fib, cuts):
    """Build the node layout determined by `fib` (list of (addr, len, hop))
    and `cuts`.  Returns (stages, used_bits, raw):

    stages    JSON-ready [{"nodes":[{"prefix":..,"rules":[..],"edges":[..]}]}]
    used_bits per-stage codec bit totals
    raw       per stage, per node: (rules, edges) with rules as (a, len, hop)
              and edges as (top-e-bits, child index)
    """
    S = len(cuts) - 1
    by_la = sorted(fib, key=lambda t: (t[1], t[0]))
    by_a = sorted(fib, key=lambda t: t[0])
    node_keys = []
    for i in range(S):
        b = cuts[i]
        if i == 0:
            node_keys.append([0])
        else:
            node_keys.append(sorted({a >> (128 - b) for (a, L, h) in fib if L > b}))
    idx = [{k: j for j, k in enumerate(ks)} for ks in node_keys]
    stages = []
    used = []
    raw = []
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        ks = node_keys[i]
        k = len(ks)
        rules = [[] for _ in range(k)]
        edges = [[] for _ in range(k)]
        if i == 0:
            for (a, L, h) in by_la:
                if L <= e:
                    rules[0].append((a, L, h))
        else:
            ii = idx[i]
            for (a, L, h) in by_la:
                if b < L <= e:
                    rules[ii[a >> (128 - b)]].append((a, L, h))
        if e < 128:
            ie = idx[i + 1]
            ii = idx[i]
            prev = -1
            for (a, L, h) in by_a:
                if L > e:
                    ck = a >> (128 - e)
                    if ck != prev:
                        prev = ck
                        edges[ii[a >> (128 - b)]].append((ck, ie[ck]))
        ce = 32 + align8(e - b)
        nodes = []
        U = 0
        rawstage = []
        sh = 128 - b
        for j in range(k):
            key = ks[j]
            rj = rules[j]
            ej = edges[j]
            cost = 128 + len(ej) * ce
            for (a, L, h) in rj:
                cost += 32 + align8(L - b)
            U += align64(cost)
            nodes.append({
                'prefix': fmt_addr(key << sh) + '/' + str(b),
                'rules': [{'prefix': fmt_addr(a) + '/' + str(L), 'hop': h}
                          for (a, L, h) in rj],
                'edges': [{'prefix': fmt_addr(ck << (128 - e)) + '/' + str(e),
                           'child': c} for (ck, c) in ej],
            })
            rawstage.append((rj, ej))
        stages.append({'nodes': nodes})
        used.append(U)
        raw.append(rawstage)
    return stages, used, raw


def peak_fraction(used, caps):
    """Exact max_i used[i]/caps[i] in lowest terms, as (num, den)."""
    num, den = 0, 1
    for u, c in zip(used, caps):
        if u * den > num * c:
            g = math.gcd(u, c)
            num, den = u // g, c // g
    return num, den


# ---------------------------------------------------------------------------
# Exact optimal cut selection
# ---------------------------------------------------------------------------

def solve_py(fib, caps, stride):
    """Pure-Python fallback of the exact optimizer (same algorithm as core.c)."""
    S = len(caps)
    ch0 = [-1]
    ch1 = [-1]
    mk = [0]
    dep = [0]
    for (a, L, h) in fib:
        v = 0
        for b in range(L):
            if (a >> (127 - b)) & 1:
                c = ch1[v]
                if c < 0:
                    c = len(ch0)
                    ch0.append(-1)
                    ch1.append(-1)
                    mk.append(0)
                    dep.append(b + 1)
                    ch1[v] = c
                v = c
            else:
                c = ch0[v]
                if c < 0:
                    c = len(ch0)
                    ch0.append(-1)
                    ch1.append(-1)
                    mk.append(0)
                    dep.append(b + 1)
                    ch0[v] = c
                v = c
        mk[v] = 1
    cnt = len(ch0)
    buckets = [[] for _ in range(129)]
    for v in range(1, cnt):
        if ch0[v] >= 0 or ch1[v] >= 0:
            buckets[dep[v]].append(v)
    g = [[0] * 129 for _ in range(128)]
    for b in range(128):
        maxe = b + stride
        if maxe > 128:
            maxe = 128
        Lb = [0] if b == 0 else buckets[b]
        k = len(Lb)
        R = [0] * k
        if b == 0 and mk[0]:
            R[0] = 32
        fnode = list(Lb)
        fv = list(range(k))
        fsize = k
        for e in range(b + 1, maxe + 1):
            delta = 32 + align8(e - b)
            ec = [0] * k
            nnode = []
            nfv = []
            ap_n = nnode.append
            ap_v = nfv.append
            for t in range(fsize):
                w = fnode[t]
                vi = fv[t]
                c = ch0[w]
                if c >= 0:
                    if mk[c]:
                        R[vi] += delta
                    if ch0[c] >= 0 or ch1[c] >= 0:
                        ap_n(c)
                        ap_v(vi)
                        ec[vi] += 1
                c = ch1[w]
                if c >= 0:
                    if mk[c]:
                        R[vi] += delta
                    if ch0[c] >= 0 or ch1[c] >= 0:
                        ap_n(c)
                        ap_v(vi)
                        ec[vi] += 1
            U = 0
            for i in range(k):
                U += align64(128 + R[i] + ec[i] * delta)
            g[b][e] = U
            fnode = nnode
            fv = nfv
            fsize = len(nnode)
    bnum = [[None] * 129 for _ in range(S)]
    bden = [[1] * 129 for _ in range(S)]
    par = [[-1] * 129 for _ in range(S)]
    for d in range(1, min(stride, 128) + 1):
        u = g[0][d]
        if u <= caps[0]:
            bnum[0][d] = u
            bden[0][d] = caps[0]
            par[0][d] = 0
    for s in range(1, S):
        cap = caps[s]
        pnum = bnum[s - 1]
        pden = bden[s - 1]
        cnum = bnum[s]
        cden = bden[s]
        cpar = par[s]
        for d in range(1, 129):
            best = None
            bestd = 1
            bestp = -1
            plo = d - stride
            if plo < 0:
                plo = 0
            for p in range(plo, d):
                pn = pnum[p]
                if pn is None:
                    continue
                u = g[p][d]
                if u > cap:
                    continue
                if u * pden[p] > pn * cap:
                    n2, d2 = u, cap
                else:
                    n2, d2 = pn, pden[p]
                if best is None or n2 * bestd < best * d2:
                    best, bestd, bestp = n2, d2, p
            cnum[d] = best
            cden[d] = bestd
            cpar[d] = bestp
    if bnum[S - 1][128] is None:
        return None
    cuts = [0] * (S + 1)
    cuts[S] = 128
    d = 128
    for s in range(S - 1, 0, -1):
        d = par[s][d]
        cuts[s] = d
    return cuts


_CORE = None
_CORE_TRIED = False


def _build_dirs():
    """Candidate writable directories for the runtime-built shared object."""
    dirs = []
    try:
        dirs.append(tempfile.mkdtemp(prefix='ipv6core-'))
    except Exception:
        pass
    for d in (HERE, os.getcwd(), os.path.expanduser('~'), '/var/tmp', '/tmp'):
        try:
            if d and os.path.isdir(d) and os.access(d, os.W_OK):
                dirs.append(d)
        except Exception:
            pass
    return dirs


def _load_core():
    src = os.path.join(HERE, 'core.c')
    if not os.path.isfile(src):
        return None
    tag = '%d' % os.getpid()
    for d in _build_dirs():
        so = os.path.join(d, 'ipv6core-%s.so' % tag)
        for cc in (('cc',), ('gcc',), ('clang',)):
            try:
                r = subprocess.run(
                    list(cc) + ['-O1', '-shared', '-fPIC', '-o', so, src],
                    stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120)
            except Exception:
                continue
            if r.returncode == 0 and os.path.exists(so):
                try:
                    lib = ctypes.CDLL(so)
                    lib.solve.argtypes = [
                        ctypes.POINTER(ctypes.c_uint64),
                        ctypes.POINTER(ctypes.c_int),
                        ctypes.c_int,
                        ctypes.POINTER(ctypes.c_uint64),
                        ctypes.c_int,
                        ctypes.c_int,
                        ctypes.POINTER(ctypes.c_int),
                    ]
                    lib.solve.restype = ctypes.c_int
                except Exception:
                    return None

                def call(fib, caps, stride, _lib=lib):
                    n = len(fib)
                    S = len(caps)
                    flat = array.array('Q')
                    for a, L, h in fib:
                        flat.append(a >> 64)
                        flat.append(a & 0xFFFFFFFFFFFFFFFF)
                    lens = array.array('i', [t[1] for t in fib])
                    if n == 0:
                        flat.append(0)
                        lens.append(0)
                    capsa = array.array('Q', caps)
                    a_ptr = (ctypes.c_uint64 * len(flat)).from_buffer(flat)
                    l_ptr = (ctypes.c_int * len(lens)).from_buffer(lens)
                    c_ptr = (ctypes.c_uint64 * len(capsa)).from_buffer(capsa)
                    out = (ctypes.c_int * (S + 1))()
                    rc = _lib.solve(a_ptr, l_ptr, n, c_ptr, S, stride, out)
                    if rc == 1:
                        return list(out)
                    if rc == 0:
                        return None
                    raise RuntimeError('core solver error %d' % rc)

                return call
    return None


def solve_cuts(fib, caps, stride):
    """Optimal feasible cuts, or None when the instance is infeasible."""
    global _CORE, _CORE_TRIED
    if len(caps) * stride < 128:
        return None
    if not _CORE_TRIED:
        _CORE_TRIED = True
        try:
            _CORE = _load_core()
        except Exception:
            _CORE = None
    if _CORE is not None:
        try:
            return _CORE(fib, caps, stride)
        except Exception:
            traceback.print_exc(file=sys.stderr)
            _CORE = None
    return solve_py(fib, caps, stride)


# ---------------------------------------------------------------------------
# Request handling: compile
# ---------------------------------------------------------------------------

def handle_compile(req):
    fib_in = req['fib']
    if type(fib_in) is not list or len(fib_in) > 2048:
        raise Invalid()
    fib = []
    seen = set()
    for rec in fib_in:
        if (type(rec) is not dict or len(rec) != 2 or
                'prefix' not in rec or 'hop' not in rec):
            raise Invalid()
        a, L = parse_prefix(rec['prefix'])
        hop = rec['hop']
        if type(hop) is not int or hop < 0 or hop > 65535:
            raise Invalid()
        key = (a << 8) | L
        if key in seen:
            raise Invalid()
        seen.add(key)
        fib.append((a, L, hop))
    caps = req['capacities']
    if type(caps) is not list:
        raise Invalid()
    S = len(caps)
    if S < 4 or S > 16:
        raise Invalid()
    for c in caps:
        if type(c) is not int or c < 1 or c > 1000000000:
            raise Invalid()
    stride = req['max_stride']
    if type(stride) is not int or stride < 1 or stride > 32:
        raise Invalid()
    cuts = solve_cuts(fib, caps, stride)
    if cuts is None:
        return {'status': 'infeasible'}
    stages, used, raw = build_layout(fib, cuts)
    num, den = peak_fraction(used, caps)
    return {
        'status': 'ok',
        'capacities': list(caps),
        'max_stride': stride,
        'cuts': list(cuts),
        'stages': stages,
        'used_bits': used,
        'peak': {'num': num, 'den': den},
    }


# ---------------------------------------------------------------------------
# Request handling: lookup
# ---------------------------------------------------------------------------

_IMG_KEYS = frozenset(('status', 'capacities', 'max_stride', 'cuts', 'stages',
                       'used_bits', 'peak'))


def validate_image(img):
    """Full structural, ordering, accounting and reachability validation of a
    lookup image.  Returns (cuts, raw) for query processing."""
    if type(img) is not dict or frozenset(img.keys()) != _IMG_KEYS:
        raise Invalid()
    if type(img['status']) is not str or img['status'] != 'ok':
        raise Invalid()
    caps = img['capacities']
    if type(caps) is not list:
        raise Invalid()
    S = len(caps)
    if S < 4 or S > 16:
        raise Invalid()
    for c in caps:
        if type(c) is not int or c < 1 or c > 1000000000:
            raise Invalid()
    stride = img['max_stride']
    if type(stride) is not int or stride < 1 or stride > 32:
        raise Invalid()
    cuts = img['cuts']
    if type(cuts) is not list or len(cuts) != S + 1:
        raise Invalid()
    for x in cuts:
        if type(x) is not int or x < 0 or x > 128:
            raise Invalid()
    if cuts[0] != 0 or cuts[S] != 128:
        raise Invalid()
    for i in range(S):
        gap = cuts[i + 1] - cuts[i]
        if gap < 1 or gap > stride:
            raise Invalid()
    stages_in = img['stages']
    if type(stages_in) is not list or len(stages_in) != S:
        raise Invalid()
    fib = []
    seen = set()
    for st in stages_in:
        if type(st) is not dict or len(st) != 1 or 'nodes' not in st:
            raise Invalid()
        nodes = st['nodes']
        if type(nodes) is not list:
            raise Invalid()
        for nd in nodes:
            if (type(nd) is not dict or len(nd) != 3 or
                    'prefix' not in nd or 'rules' not in nd or 'edges' not in nd):
                raise Invalid()
            if type(nd['prefix']) is not str:
                raise Invalid()
            rules = nd['rules']
            edges = nd['edges']
            if type(rules) is not list or type(edges) is not list:
                raise Invalid()
            for r in rules:
                if (type(r) is not dict or len(r) != 2 or
                        'prefix' not in r or 'hop' not in r):
                    raise Invalid()
                a, L = parse_prefix(r['prefix'])
                if fmt_prefix(a, L) != r['prefix']:
                    raise Invalid()
                hop = r['hop']
                if type(hop) is not int or hop < 0 or hop > 65535:
                    raise Invalid()
                key = (a << 8) | L
                if key in seen:
                    raise Invalid()
                seen.add(key)
                fib.append((a, L, hop))
            for ed in edges:
                if (type(ed) is not dict or len(ed) != 2 or
                        'prefix' not in ed or 'child' not in ed):
                    raise Invalid()
                if type(ed['prefix']) is not str:
                    raise Invalid()
                child = ed['child']
                if type(child) is not int or child < 0:
                    raise Invalid()
    if len(fib) > 2048:
        raise Invalid()
    stages_exp, used, raw = build_layout(fib, cuts)
    if stages_exp != stages_in:
        raise Invalid()
    ub = img['used_bits']
    if type(ub) is not list or len(ub) != S:
        raise Invalid()
    for x in ub:
        if type(x) is not int or x < 0:
            raise Invalid()
    if ub != used:
        raise Invalid()
    for i in range(S):
        if used[i] > caps[i]:
            raise Invalid()
    pk = img['peak']
    if (type(pk) is not dict or len(pk) != 2 or
            'num' not in pk or 'den' not in pk):
        raise Invalid()
    num = pk['num']
    den = pk['den']
    if type(num) is not int or type(den) is not int or num < 0 or den <= 0:
        raise Invalid()
    exp_num, exp_den = peak_fraction(used, caps)
    if num != exp_num or den != exp_den:
        raise Invalid()
    return cuts, raw


def build_lut(raw, cuts):
    """Per-node lookup structures: (lengths desc, rule map, edge keys, children)."""
    S = len(cuts) - 1
    lut = []
    for i in range(S):
        stage = []
        for (rj, ej) in raw[i]:
            rmap = {}
            lenset = set()
            for (a, L, h) in rj:
                rmap[(a >> (128 - L) << 8) | L] = h
                lenset.add(L)
            ekeys = [ck for (ck, c) in ej]
            echild = [c for (ck, c) in ej]
            stage.append((sorted(lenset, reverse=True), rmap, ekeys, echild))
        lut.append(stage)
    return lut


def handle_lookup(req):
    addrs_in = req['addresses']
    if type(addrs_in) is not list or len(addrs_in) > 20000:
        raise Invalid()
    cuts, raw = validate_image(req['image'])
    lut = build_lut(raw, cuts)
    S = len(cuts) - 1
    bl = bisect.bisect_left
    answers = []
    append = answers.append
    for s in addrs_in:
        addr = parse_addr(s)
        besth = None
        bestl = None
        ni = 0
        for i in range(S):
            ld, rmap, ekeys, echild = lut[i][ni]
            for L in ld:
                h = rmap.get((addr >> (128 - L) << 8) | L)
                if h is not None:
                    if bestl is None or L > bestl:
                        besth = h
                        bestl = L
                    break
            if i == S - 1:
                break
            e = cuts[i + 1]
            q = addr >> (128 - e)
            j = bl(ekeys, q)
            if j < len(ekeys) and ekeys[j] == q:
                ni = echild[j]
            else:
                break
        append({'hop': besth, 'prefix_length': bestl})
    return {'status': 'ok', 'answers': answers}


# ---------------------------------------------------------------------------
# JSON transport
# ---------------------------------------------------------------------------

def _pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid()
        d[k] = v
    return d


def _bad_const(name):
    raise Invalid()


_JSON_STR = re.compile(r'"(?:[^"\\]|\\.)*"', re.S)


def parse_request(line):
    """Strict JSON parse of one request line; raises Invalid on any problem.

    Very large lines are structurally pre-screened so that a hostile line
    cannot exhaust memory before the parse is rejected: valid requests never
    contain more than a bounded number of JSON values.
    """
    if len(line) > 1000000:
        stripped = _JSON_STR.sub('""', line)
        nstruct = (stripped.count(',') + stripped.count(':') +
                   stripped.count('[') + stripped.count('{'))
        if nstruct > 2000000:
            raise Invalid()
    try:
        return json.loads(line, object_pairs_hook=_pairs,
                          parse_constant=_bad_const)
    except Invalid:
        raise
    except (ValueError, RecursionError, MemoryError, TypeError, OverflowError):
        raise Invalid()


def handle(req):
    if type(req) is not dict:
        raise Invalid()
    op = req.get('op')
    if op == 'compile':
        if frozenset(req.keys()) != frozenset(('op', 'fib', 'capacities', 'max_stride')):
            raise Invalid()
        return handle_compile(req)
    if op == 'lookup':
        if frozenset(req.keys()) != frozenset(('op', 'image', 'addresses')):
            raise Invalid()
        return handle_lookup(req)
    raise Invalid()


def main():
    stdin = sys.stdin.buffer
    stdout = sys.stdout
    dumps = json.JSONEncoder(separators=(',', ':')).encode
    while True:
        raw = stdin.readline()
        if not raw:
            break
        try:
            line = raw.decode('utf-8')
        except UnicodeDecodeError:
            resp = {'status': 'invalid'}
        else:
            try:
                resp = handle(parse_request(line))
            except Invalid:
                resp = {'status': 'invalid'}
            except (MemoryError, RecursionError):
                resp = {'status': 'invalid'}
            except Exception:
                traceback.print_exc(file=sys.stderr)
                resp = {'status': 'invalid'}
        stdout.write(dumps(resp))
        stdout.write('\n')
        stdout.flush()


if __name__ == '__main__':
    main()
